class Solution { int[] a;int side;int[]s=new int[4];boolean dfs(int i){if(i==a.length)return true;Set<Integer> tried=new HashSet<>();for(int k=0;k<4;k++){if(tried.contains(s[k])||s[k]+a[i]>side)continue;tried.add(s[k]);s[k]+=a[i];if(dfs(i+1))return true;s[k]-=a[i];if(s[k]==0)return false;}return false;}public boolean makesquare(int[] x){int total=0;for(int v:x)total+=v;if(total%4!=0)return false;a=x.clone();Arrays.sort(a);for(int i=0,j=a.length-1;i<j;i++,j--){int t=a[i];a[i]=a[j];a[j]=t;}side=total/4;if(a[0]>side)return false;Arrays.fill(s,0);return dfs(0);} }
